import { useState } from 'react';

export default function Counter() {
  const [count, setCount] = useState(0);

  return (
    <div>
      <p>Count: {count}</p>
      <button onClick={() => setCount((c) => c - 1)}>−1</button>
      <button onClick={() => setCount((c) => c + 1)}>+1</button>
      <button onClick={() => setCount(0)} disabled={count === 0}>
        Reset
      </button>
    </div>
  );
}

import { useState } from 'react';

export default function SignupForm() {
  const [form, setForm] = useState({ name: '', email: '', plan: 'free' });
  const [submitted, setSubmitted] = useState(null);

  function handleChange(e) {
    const { name, value } = e.target;
    setForm({ ...form, [name]: value });
  }

  function handleSubmit(e) {
    e.preventDefault();
    setSubmitted(form);
  }

  const valid = form.name.trim() !== '' && form.email.includes('@');

  return (
    <form onSubmit={handleSubmit}>
      <label>
        Name
        <input name="name" value={form.name} onChange={handleChange} />
      </label>
      <label>
        Email
        <input name="email" type="email" value={form.email} onChange={handleChange} />
      </label>
      <label>
        Plan
        <select name="plan" value={form.plan} onChange={handleChange}>
          <option value="free">Free</option>
          <option value="pro">Pro</option>
        </select>
      </label>
      <button type="submit" disabled={!valid}>
        Sign up
      </button>
      {submitted && (
        <p>
          Welcome, {submitted.name}! You chose the {submitted.plan} plan.
        </p>
      )}
    </form>
  );
}

import { useState } from 'react';

let nextId = 1;

export default function TodoList() {
  const [todos, setTodos] = useState([]);
  const [text, setText] = useState('');

  function addTodo(e) {
    e.preventDefault();
    const title = text.trim();
    if (!title) return;
    setTodos([...todos, { id: nextId++, title, done: false }]);
    setText('');
  }

  function toggle(id) {
    setTodos(todos.map((t) => (t.id === id ? { ...t, done: !t.done } : t)));
  }

  function remove(id) {
    setTodos(todos.filter((t) => t.id !== id));
  }

  return (
    <>
      <form onSubmit={addTodo}>
        <input value={text} onChange={(e) => setText(e.target.value)} placeholder="New todo" />
        <button>Add</button>
      </form>
      {todos.length === 0 ? (
        <p>Nothing to do.</p>
      ) : (
        <ul>
          {todos.map((todo) => (
            <li key={todo.id}>
              <label>
                <input type="checkbox" checked={todo.done} onChange={() => toggle(todo.id)} />
                <span style={{ textDecoration: todo.done ? 'line-through' : 'none' }}>{todo.title}</span>
              </label>
              <button onClick={() => remove(todo.id)}>Delete</button>
            </li>
          ))}
        </ul>
      )}
    </>
  );
}

import { useEffect, useState } from 'react';

export default function Post({ id }) {
  const [post, setPost] = useState(null);
  const [status, setStatus] = useState('loading');

  useEffect(() => {
    const controller = new AbortController();
    setStatus('loading');

    fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, { signal: controller.signal })
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json();
      })
      .then((data) => {
        setPost(data);
        setStatus('ready');
      })
      .catch((err) => {
        if (err.name !== 'AbortError') setStatus('error');
      });

    return () => controller.abort();
  }, [id]);

  if (status === 'loading') return <p>Loading…</p>;
  if (status === 'error') return <p>Could not load post {id}.</p>;

  return (
    <article>
      <h2>{post.title}</h2>
      <p>{post.body}</p>
    </article>
  );
}

import { createContext, useContext, useState } from 'react';

const ThemeContext = createContext(undefined);

export function ThemeProvider({ children }) {
  const [theme, setTheme] = useState('light');
  const toggle = () => setTheme((t) => (t === 'light' ? 'dark' : 'light'));
  return <ThemeContext value={{ theme, toggle }}>{children}</ThemeContext>;
}

export function useTheme() {
  const ctx = useContext(ThemeContext);
  if (ctx === undefined) throw new Error('useTheme must be used inside <ThemeProvider>');
  return ctx;
}

function ThemeToggle() {
  const { theme, toggle } = useTheme();
  return <button onClick={toggle}>Switch to {theme === 'light' ? 'dark' : 'light'} mode</button>;
}

function Page() {
  const { theme } = useTheme();
  return (
    <main className={`page ${theme}`}>
      <h1>Settings</h1>
      <ThemeToggle />
    </main>
  );
}

export default function App() {
  return (
    <ThemeProvider>
      <Page />
    </ThemeProvider>
  );
}

import { useEffect, useState } from 'react';

export function useLocalStorage(key, initialValue) {
  const [value, setValue] = useState(() => {
    try {
      const stored = localStorage.getItem(key);
      return stored === null ? initialValue : JSON.parse(stored);
    } catch {
      return initialValue;
    }
  });

  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);

  return [value, setValue];
}

export default function Preferences() {
  const [name, setName] = useLocalStorage('name', '');
  const [notifications, setNotifications] = useLocalStorage('notifications', true);

  return (
    <form>
      <label>
        Display name
        <input value={name} onChange={(e) => setName(e.target.value)} />
      </label>
      <label>
        <input
          type="checkbox"
          checked={notifications}
          onChange={(e) => setNotifications(e.target.checked)}
        />
        Email notifications
      </label>
    </form>
  );
}

import { useEffect, useRef } from 'react';

export default function SearchDialog({ onClose }) {
  const inputRef = useRef(null);

  useEffect(() => {
    inputRef.current.focus();
  }, []);

  return (
    <div role="dialog" aria-labelledby="search-title">
      <h2 id="search-title">Search</h2>
      <input ref={inputRef} type="search" placeholder="Type to search" />
      <button onClick={onClose}>Close</button>
    </div>
  );
}

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { BrowserRouter, Routes, Route, NavLink, Outlet, useParams } from 'react-router';

const articles = { intro: 'Getting started', hooks: 'Thinking in hooks' };

function Layout() {
  return (
    <>
      <nav>
        <NavLink to="/" end>Home</NavLink>
        <NavLink to="/articles">Articles</NavLink>
      </nav>
      <main>
        <Outlet />
      </main>
    </>
  );
}

function Home() {
  return <h1>Welcome</h1>;
}

function ArticleList() {
  return (
    <ul>
      {Object.entries(articles).map(([slug, title]) => (
        <li key={slug}>
          <NavLink to={`/articles/${slug}`}>{title}</NavLink>
        </li>
      ))}
    </ul>
  );
}

function Article() {
  const { slug } = useParams();
  const title = articles[slug];
  return title ? <h1>{title}</h1> : <h1>Article not found</h1>;
}

function NotFound() {
  return <h1>Page not found</h1>;
}

createRoot(document.getElementById('root')).render(
  <StrictMode>
    <BrowserRouter>
      <Routes>
        <Route element={<Layout />}>
          <Route index element={<Home />} />
          <Route path="articles" element={<ArticleList />} />
          <Route path="articles/:slug" element={<Article />} />
          <Route path="*" element={<NotFound />} />
        </Route>
      </Routes>
    </BrowserRouter>
  </StrictMode>,
);

import { QueryClient, QueryClientProvider, useQuery } from '@tanstack/react-query';

const queryClient = new QueryClient();

async function fetchUsers() {
  const res = await fetch('https://jsonplaceholder.typicode.com/users');
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}

function Users() {
  const { data, isPending, isError, error, refetch, isFetching } = useQuery({
    queryKey: ['users'],
    queryFn: fetchUsers,
    staleTime: 5 * 60 * 1000,
  });

  if (isPending) return <p>Loading users…</p>;
  if (isError) return <p role="alert">Could not load users: {error.message}</p>;

  return (
    <>
      <button onClick={() => refetch()} disabled={isFetching}>
        {isFetching ? 'Refreshing…' : 'Refresh'}
      </button>
      <ul>
        {data.map((user) => (
          <li key={user.id}>
            {user.name} ({user.email})
          </li>
        ))}
      </ul>
    </>
  );
}

export default function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <Users />
    </QueryClientProvider>
  );
}

import { useActionState } from 'react';
import { useFormStatus } from 'react-dom';

async function sendMessage(previousState, formData) {
  const message = formData.get('message').trim();
  if (message.length < 10) {
    return { error: 'Please write at least 10 characters.' };
  }
  const res = await fetch('/api/messages', { method: 'POST', body: formData });
  if (!res.ok) return { error: 'Sending failed, please try again.' };
  return { success: true };
}

function SubmitButton() {
  const { pending } = useFormStatus();
  return <button disabled={pending}>{pending ? 'Sending…' : 'Send'}</button>;
}

export default function ContactForm() {
  const [state, formAction] = useActionState(sendMessage, {});

  return (
    <form action={formAction}>
      <label>
        Message
        <textarea name="message" required />
      </label>
      <SubmitButton />
      {state.error && <p role="alert">{state.error}</p>}
      {state.success && <p>Thanks, your message was sent.</p>}
    </form>
  );
}

import { memo, useMemo, useState } from 'react';

const Row = memo(function Row({ item }) {
  return (
    <li>
      {item.name} – {item.price.toFixed(2)}
    </li>
  );
});

export default function Catalog({ items }) {
  const [query, setQuery] = useState('');
  const [maxPrice, setMaxPrice] = useState(100);

  const visible = useMemo(
    () =>
      items
        .filter((item) => item.name.toLowerCase().includes(query.toLowerCase()))
        .filter((item) => item.price <= maxPrice),
    [items, query, maxPrice],
  );

  return (
    <>
      <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Filter" />
      <label>
        Max price {maxPrice}
        <input
          type="range"
          min="0"
          max="100"
          value={maxPrice}
          onChange={(e) => setMaxPrice(Number(e.target.value))}
        />
      </label>
      <p>
        {visible.length} of {items.length} items
      </p>
      <ul>
        {visible.map((item) => (
          <Row key={item.id} item={item} />
        ))}
      </ul>
    </>
  );
}

import { useState } from 'react';

function Tabs({ tabs }) {
  const [active, setActive] = useState(tabs[0].id);
  const current = tabs.find((tab) => tab.id === active);

  return (
    <div>
      <div role="tablist">
        {tabs.map((tab) => (
          <button
            key={tab.id}
            role="tab"
            aria-selected={tab.id === active}
            onClick={() => setActive(tab.id)}
          >
            {tab.label}
          </button>
        ))}
      </div>
      <div role="tabpanel">{current.content}</div>
    </div>
  );
}

export default function ProductPage() {
  return (
    <Tabs
      tabs={[
        { id: 'details', label: 'Details', content: <p>Solid oak desk, 140 × 70 cm.</p> },
        { id: 'reviews', label: 'Reviews', content: <p>No reviews yet.</p> },
        { id: 'shipping', label: 'Shipping', content: <p>Delivered in 3 to 5 days.</p> },
      ]}
    />
  );
}
